mkdir -p /workspace/tests && cat > /workspace/tests/harness.py << 'EOF'
import json, subprocess, sys, copy

BASE_CFG = {
    "early": False, "overlap": "reject", "buffer_packets": 2, "idle_ms": 0,
    "max_streams_bidi": 4, "max_streams_uni": 4, "max_stream_data": 32,
    "max_data": 64, "crypto_limit": 32, "sent": {"I": [], "H": [], "A": []},
}

def cfg(**kw):
    c = copy.deepcopy(BASE_CFG)
    c.update(kw)
    return c

def trace(tid, events, **kw):
    return {"id": tid, "config": cfg(**kw), "events": events}

def req(traces):
    return {"version": 1, "traces": traces}

def run(doc, expect_invalid=False):
    """Accepts a dict or a raw string."""
    if isinstance(doc, str):
        inp = doc
    else:
        inp = json.dumps(doc)
    p = subprocess.run([sys.executable, "-I", "/app/submission/entry.py"],
                       input=inp.encode(), stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, cwd="/app/submission")
    if p.returncode != 0:
        print("NONZERO EXIT", p.returncode, p.stderr.decode()[:400])
        return None, False
    out = p.stdout.decode()
    err = p.stderr.decode()
    if err:
        print("STDERR:", err[:500])
    try:
        parsed = json.loads(out)
    except Exception:
        print("BAD OUTPUT JSON:", out[:300])
        return None, False
    if expect_invalid:
        return parsed, parsed == {"error": "INVALID_INPUT"}
    return parsed, parsed != {"error": "INVALID_INPUT"}

def show(x):
    print(json.dumps(x, indent=1))

PASS = 0
FAIL = 0
def check(name, got, want):
    global PASS, FAIL
    if got == want:
        PASS += 1
    else:
        FAIL += 1
        print("FAIL %s" % name)
        print("  got :", json.dumps(got))
        print("  want:", json.dumps(want))

def summary():
    print("passed=%d failed=%d" % (PASS, FAIL))
EOF
